"""ASX-owned event text with independently configurable ASXUI rendering."""
from pathlib import Path
import unittest
from test_official_party_lua import STUB,LuaRuntime
ROOT=Path(__file__).resolve().parents[1]
@unittest.skipUnless(LuaRuntime,"Explicit ASXUI profile requires Lua 5.1")
class EventTests(unittest.TestCase):
    def setUp(self):
        self.lua=LuaRuntime();self.lua.execute(STUB);self.lua.execute('local create=CreateFrame;function CreateFrame(kind,...)local f=create(kind,unpack(arg));function f:GetFrameLevel()return self.level or 5 end;if kind=="Font"then function f:SetTextColor(r,g,b)self.textColor={r,g,b}end;function f:GetStringHeight()return (self.fontSize or 12)*1.2 end end;return f end');self.lua.execute("SlashCmdList={}")
        self.lua.execute('view={epoch="1",own="11",owner={discovery={event=1,title="ASX supplies title",icon="Interface/Icons/INV_Crate_01",reward="ASX reward wording",note="ASX exact receipt",color={1,.5,0}},ritual={event=2,held=700,inside=true,maximum=2000,title="ASX ritual title",note="ASX progress wording"}},blessing={boss=1,title="ASX fortune title",icon="Interface/Icons/INV_Misc_Orb_02",reward="ASX exact fortune",note="ASX fortune note",color={1,1,1}}};function ASX_GetAPIVersion()return 1,0 end;function ASX_GetState()return {available=true,session={epoch=view.epoch,recipientGUID=view.own},data={discovery=view.owner.discovery,sayge=view.owner.ritual,fortune=view.blessing},texts={supplies=view.owner.discovery,sayge=view.owner.ritual,fortune=view.blessing}}end;function tick()now=now+.2;objects.ASXUIEventsController.scripts.OnUpdate()end')
        self.lua.execute((ROOT/'addons/ASXUI/Theme.lua').read_text());self.lua.execute((ROOT/'addons/ASXUI/Events.lua').read_text());self.lua.execute('tick()')
    def run_lua(self,s):self.lua.execute(s)
    def test_sale_uses_exact_gold_and_native_coin_then_clears_for_a_buff(self):
        self.run_lua('view.owner.discovery.event=2;view.owner.discovery.gold=25;view.owner.discovery.note="Sold for 25 gold";now=now+4;tick();local t=objects.ASXSupplyDiscoveryToast;assert(t.note.text=="Sold for 25" and t.coin:IsShown() and t.coin.texture=="Interface\\\\MoneyFrame\\\\UI-GoldIcon");view.owner.discovery.event=3;view.owner.discovery.gold=0;view.owner.discovery.note="+10% damage - 60 seconds";now=now+4;tick();assert(not t.coin:IsShown() and string.find(t.note.text,"Duration:",1,true))')
    def test_popups_use_classic_wow_backdrop_and_font(self):
        self.run_lua('local f=objects.ASXSupplyDiscoveryToast;assert(f.backdrop.bgFile=="Interface\\\\DialogFrame\\\\UI-DialogBox-Background" and f.backdrop.edgeFile=="Interface\\\\DialogFrame\\\\UI-DialogBox-Border");assert(f.title.fontSize==12 and string.find(f.title.font,"FRIZQT__",1,true))')
    def test_all_semantic_text_is_displayed_verbatim_from_asx(self):
        self.run_lua('assert(objects.ASXSupplyDiscoveryToast.title.text==view.owner.discovery.title and objects.ASXSupplyDiscoveryToast.reward.text==view.owner.discovery.reward and objects.ASXSupplyDiscoveryToast.note.text==view.owner.discovery.note);assert(objects.ASXDarkmoonBlessingToast.reward.text==view.blessing.reward and objects.ASXDarkmoonBlessingToast.note.text==view.blessing.note);assert(objects.ASXSaygeTrialProgress.title.text==view.owner.ritual.title and objects.ASXSaygeTrialProgress.time.text=="13.0 s" and objects.ASXSaygeTrialProgress.note.text=="")')
    def test_bonus_numbers_are_green_labels_white_and_time_stays_inside_track(self):
        self.run_lua('assert(ASXUI_FormatBonus("+10% damage, +2 targets")=="|cff1eff00+10%|r damage, |cff1eff00+2|r targets");assert(ASXUI_FormatBonus("-2.5% haste")=="|cff1eff00-2.5%|r haste");local f=objects.ASXSaygeTrialProgress;assert(f.time.anchor[1]=="RIGHT" and f.title.anchor[1]=="LEFT" and f.time.anchor[2]==f.title.anchor[2]);view.owner.ritual.allInside=false;tick();assert(f.note.text=="Waiting for all players" and f.time.text=="13.0 s")')
    def test_actual_reward_widgets_keep_labels_white_and_supply_rarity(self):
        self.run_lua('view.blessing.boss=2;view.blessing.reward="+12% Luck";view.blessing.color={.12,1,0};view.owner.discovery.event=2;view.owner.discovery.note="+14% haste - 60 seconds";now=now+4;tick();local fortune=objects.ASXDarkmoonBlessingToast;local supply=objects.ASXSupplyDiscoveryToast;assert(fortune.reward.text=="|cff1eff00+12%|r Luck" and fortune.reward.textColor[1]==1 and fortune.reward.textColor[2]==1 and fortune.reward.textColor[3]==1);assert(supply.note.text=="|cff1eff00+14%|r haste\\nDuration: |cff1eff0060|r seconds" and supply.note.textColor[1]==1 and supply.note.textColor[2]==1 and supply.note.textColor[3]==1);assert(supply.reward.text==view.owner.discovery.reward and supply.reward.textColor[2]==.5)')
    def test_position_scale_opacity_visibility_and_reset_are_per_widget(self):
        self.run_lua('assert(ASXUI_ConfigureWidget("supplies","position","120","-210"));assert(ASXUI_ConfigureWidget("supplies","scale","1.4"));assert(ASXUI_ConfigureWidget("supplies","opacity","0.45"));local f=objects.ASXSupplyDiscoveryToast;assert(math.abs(f.anchor[4]-120/1.4)<.001 and f.anchor[2]==objects.ASXUIEventAnchor and f.scale==1.4 and f.alpha==.45);assert(objects.ASXDarkmoonBlessingToast.alpha==1);assert(ASXUI_ConfigureWidget("sayge","show","off"));assert(not objects.ASXSaygeTrialProgress.shown and view.owner.ritual.held==700);assert(ASXUI_ConfigureWidget("sayge","show","on"));assert(objects.ASXSaygeTrialProgress.shown);assert(ASXUI_ConfigureWidget("supplies","reset"));assert(f.anchor[4]==0 and f.anchor[5]==-66 and f.scale==1 and f.alpha==1)')
    def test_slash_commands_apply_immediately_to_persistent_preferences(self):
        self.lua.execute((ROOT/'addons/ASXUI/ASXUI.lua').read_text())
        self.run_lua('SlashCmdList.ASXUI("widget supplies position 90 -190");SlashCmdList.ASXUI("widget supplies opacity 0.6");assert(objects.ASXSupplyDiscoveryToast.anchor[4]==90 and objects.ASXSupplyDiscoveryToast.alpha==.6);saved=ASXUIDB.widgets;SlashCmdList.ASXUI("widget sayge show off");assert(not objects.ASXSaygeTrialProgress.shown);SlashCmdList.ASXUI("widget sayge reset");assert(objects.ASXSaygeTrialProgress.shown);SlashCmdList.ASXUI("widget sayge scale bad");assert(ASXUIDB.widgets.sayge.scale==1)')
    def test_shared_anchor_stacks_scaled_visible_widgets_and_tracks_hud_top(self):
        self.run_lua('local a=objects.ASXUIEventAnchor;assert(a.anchor[2]==UIParent and a.anchor[4]==0 and a.anchor[5]==-125);local sayge=objects.ASXSaygeTrialProgress;local supply=objects.ASXSupplyDiscoveryToast;local fortune=objects.ASXDarkmoonBlessingToast;assert(sayge.anchor[2]==a and sayge.anchor[5]==0 and supply.anchor[5]==-66 and fortune.anchor[5]==-158);ASXUI_ConfigureWidget("sayge","scale","2");assert(supply.anchor[5]==-120 and fortune.anchor[5]==-212);ASXUI_ConfigureWidget("sayge","show","off");assert(supply.anchor[5]==0 and fortune.anchor[5]==-92);assert(ASXUI_ConfigureWidget("anchor","position","10","-100"));assert(a.anchor[4]==10 and a.anchor[5]==-100)')
    def test_previous_default_anchor_migrates_once_custom_positions_and_reset_are_preserved(self):
        self.run_lua('ASXUIDB={eventAnchor={x=0,y=-85}};tick();assert(ASXUIDB.eventAnchor.y==-125);ASXUI_ConfigureWidget("anchor","position","0","-85");tick();assert(ASXUIDB.eventAnchor.y==-85);ASXUIDB={eventAnchor={x=10,y=-85}};tick();assert(ASXUIDB.eventAnchor.x==10 and ASXUIDB.eventAnchor.y==-85);ASXUI_ConfigureWidget("anchor","reset");assert(ASXUIDB.eventAnchor.y==-125)')
    def test_compact_popup_grows_for_wrapped_text_and_stack_uses_real_height(self):
        self.run_lua('local f=objects.ASXSupplyDiscoveryToast;assert(f:GetWidth()==320 and f:GetHeight()==80 and f.icon:GetWidth()==32);function f.title:GetStringHeight()return 14 end;function f.reward:GetStringHeight()return 36 end;function f.note:GetStringHeight()return 28 end;tick();assert(f:GetHeight()==110);assert(objects.ASXDarkmoonBlessingToast.anchor[5]==f.anchor[5]-110-12)')
    def test_fortune_does_not_replay_on_missing_data_new_epoch_or_new_trial(self):
        self.run_lua('now=now+10;tick();assert(not objects.ASXDarkmoonBlessingToast.shown);local getter=ASX_GetState;ASX_GetState=nil;tick();ASX_GetState=getter;view.epoch="2";view.owner.ritual.event=3;tick();assert(not objects.ASXDarkmoonBlessingToast.shown);view.blessing.boss=2;tick();assert(objects.ASXDarkmoonBlessingToast.shown)')
    def test_fortune_popup_is_not_rearmed_by_choice_or_transient_clock_rollback(self):
        self.run_lua('phase="choosing";for i=1,40 do tick()end;phase="playing";tick();assert(not objects.ASXDarkmoonBlessingToast.shown);function AZS_GetRunTime()return 0 end;tick();assert(not objects.ASXDarkmoonBlessingToast.shown);view.owner.ritual.event=99;tick();assert(not objects.ASXDarkmoonBlessingToast.shown)')
    def test_fortune_receipt_announces_identical_rewards_once_and_defers_new_receipts(self):
        self.run_lua('view.blessing.event=101;tick();now=now+8;tick();assert(not objects.ASXDarkmoonBlessingToast.shown);view.blessing.best=9000;view.epoch="2";tick();assert(not objects.ASXDarkmoonBlessingToast.shown);phase="choosing";view.blessing.event=102;tick();phase="playing";tick();assert(objects.ASXDarkmoonBlessingToast.shown);now=now+8;tick();assert(not objects.ASXDarkmoonBlessingToast.shown)')
    def test_old_absolute_positions_migrate_to_relative_offsets(self):
        self.run_lua('ASXUIDB={widgets={supplies={x=20,y=-180},fortune={y=-260},sayge={y=-75}}};tick();assert(ASXUIDB.widgetLayoutVersion==2 and ASXUIDB.widgets.supplies.y==-40 and ASXUIDB.widgets.fortune.y==0 and ASXUIDB.widgets.sayge.y==0)')
    def test_invalid_inputs_do_not_change_valid_preferences(self):
        self.run_lua('assert(ASXUI_ConfigureWidget("sayge","scale","1.5"));for _,v in ipairs({"0","3","nan","inf","bad"})do assert(not ASXUI_ConfigureWidget("sayge","scale",v))end;assert(not ASXUI_ConfigureWidget("sayge","opacity","2"));assert(not ASXUI_ConfigureWidget("sayge","position","5000","0"));assert(not ASXUI_ConfigureWidget("other","show","off"));assert(ASXUIDB.widgets.sayge.scale==1.5)')
    def test_saved_corrupt_preferences_are_repaired(self):
        self.run_lua('ASXUIDB={widgets={sayge={scale=0/0,opacity=math.huge,x="bad",visible="yes"}}};tick();local p=ASXUIDB.widgets.sayge;assert(p.scale==1 and p.opacity==1 and p.x==0 and p.visible==true)')
    def test_visibility_consumes_notifications_without_replay(self):
        self.run_lua('ASXUI_ConfigureWidget("supplies","show","off");now=now+5;tick();ASXUI_ConfigureWidget("supplies","show","on");assert(not objects.ASXSupplyDiscoveryToast.shown);view.owner.discovery.event=2;tick();assert(objects.ASXSupplyDiscoveryToast.shown)')
    def test_missing_bridge_hides_all_widgets_without_fabricating_text(self):
        self.run_lua('ASX_GetState=nil;tick();assert(not objects.ASXSupplyDiscoveryToast.shown and not objects.ASXDarkmoonBlessingToast.shown and not objects.ASXSaygeTrialProgress.shown)')
    def test_unsupported_public_major_hides_views_without_using_legacy_bridge(self):
        self.run_lua('function ASX_GetEventPresentation()error("legacy bridge used")end;function ASX_GetAPIVersion()return 2,0 end;tick();assert(not objects.ASXSupplyDiscoveryToast.shown and not objects.ASXDarkmoonBlessingToast.shown and not objects.ASXSaygeTrialProgress.shown)')
    def test_new_recipient_retires_old_queue_and_progress_identity(self):
        self.run_lua('view.owner.discovery={event=2,title="Queued old",icon="icon",reward="Old",note="Old",color={1,1,1}};tick();view.epoch="2";view.own="22";view.owner.discovery={event=1,title="New owner",icon="icon",reward="New owner",note="New",color={1,1,1}};view.owner.ritual.held=100;tick();assert(objects.ASXSupplyDiscoveryToast.reward.text=="New owner");assert(objects.ASXSaygeTrialProgress.rendered==100)')
if __name__=='__main__':unittest.main()
